begin;
create table public.case_reviews(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),kind text not null check(kind in('second_opinion','appeal_review')),reviewer_id uuid not null references auth.users(id),assigned_by uuid not null references auth.users(id),mandatory boolean not null,status text not null default 'pending' check(status in('pending','completed','cancelled')),basis_hash text not null,recommendation text,note text not null default '',assignment_reason text not null,recorded_at timestamptz,evidence_ids uuid[] not null default '{}',created_at timestamptz not null default now());
create index on public.case_reviews(application_id,status);
create table public.delivery_outbox(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id),recipient_id uuid not null references auth.users(id),channel text not null check(channel in('in_app','smtp_local')),generation int not null,source_hash text not null,status text not null default 'pending' check(status in('pending','processing','in_app_delivered','smtp_accepted','ambiguous','retry_wait','exhausted','superseded','cancelled')),attempts int not null default 0,title text not null,body text not null,created_at timestamptz not null default now(),scheduled_for timestamptz not null default now(),lease_until timestamptz,last_error text,accepted_at timestamptz);
create index on public.delivery_outbox(status,scheduled_for);
create table public.worker_health(id text primary key,last_seen_at timestamptz not null,detail jsonb not null default '{}');
create table fp_private.delivery_leases(id uuid primary key references public.delivery_outbox(id),token uuid not null);
alter table public.notifications add column outbox_id uuid unique references public.delivery_outbox(id);
alter table public.case_reviews enable row level security;alter table public.delivery_outbox enable row level security;alter table public.worker_health enable row level security;
revoke all on public.case_reviews,public.delivery_outbox,public.worker_health from public,anon,authenticated;grant select on public.case_reviews,public.delivery_outbox,public.worker_health to authenticated;grant all on public.case_reviews,public.delivery_outbox,public.worker_health to service_role;
create policy scoped_review_read on public.case_reviews for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and fp_private.can_view(a.id)));
create policy scoped_delivery_read on public.delivery_outbox for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and fp_private.can_view(a.id)));
create policy worker_health_read on public.worker_health for select to authenticated using(fp_private.has_role('national_admin') or fp_private.has_role('regional_officer'));
create function fp_private.case_content(_id uuid) returns text language sql stable security definer set search_path='' as $$
 select encode(sha256(convert_to(jsonb_build_object('form',a.form_data,'policy',a.template_snapshot,'scope_revision',a.scope_revision,'scope_items',(select coalesce(jsonb_agg(to_jsonb(s) order by s.id),'[]') from public.application_scope_items s where s.application_id=a.id),'links',(select coalesce(jsonb_agg(to_jsonb(l) order by l.claim_id,l.document_id),'[]') from public.claim_evidence l join public.application_claims c on c.id=l.claim_id where c.application_id=a.id),'deficiencies',(select coalesce(jsonb_agg(to_jsonb(d) order by d.id),'[]') from public.deficiencies d where d.application_id=a.id),'claims',(select coalesce(jsonb_agg(to_jsonb(c)-'updated_at' order by c.id),'[]') from public.application_claims c where c.application_id=a.id),'evidence',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'hash',d.sha256,'scan',d.scan_status,'validity',d.validity_mode,'expiry',d.expires_on,'reviewed',d.validity_reviewed_at) order by d.id),'[]') from public.application_documents d where d.application_id=a.id),'visits',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'report',v.report,'completed',v.completed_at,'panel',v.panel_snapshot) order by v.id),'[]') from public.evc_visits v where v.application_id=a.id))::text,'UTF8')),'hex') from public.applications a where a.id=_id
$$;
create function fp_private.delivery_source(_id uuid,_recipient uuid) returns text language sql stable security definer set search_path='' as $$select encode(sha256(convert_to(jsonb_build_object('content',fp_private.case_content(a.id),'version',a.version,'status',a.status,'due',a.sla_due_at,'owner',a.owner_id,'recipient',_recipient,'recipient_state',(select jsonb_build_object('confirmed',u.email_confirmed_at,'banned',u.banned_until) from auth.users u where u.id=_recipient),'grant',(select jsonb_agg(to_jsonb(g) order by g.role,g.region) from public.user_roles g where g.user_id=_recipient and g.active and g.revoked_at is null and(g.expires_at is null or g.expires_at>clock_timestamp())) )::text,'UTF8')),'hex') from public.applications a where a.id=_id$$;
create function fp_private.can_manage_case(a public.applications) returns boolean language sql stable security definer set search_path='' as $$select fp_private.actor()<>a.owner_id and(fp_private.has_role('national_admin') or fp_private.has_role('regional_officer',a.region))$$;
create function fp_private.candidates(_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.applications;
begin select * into a from public.applications where id=_id;if a.id is null or not fp_private.can_view(a.id) or not fp_private.can_manage_case(a) then raise exception 'Case management scope required' using errcode='42501';end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'name',coalesce(p.full_name,'Workspace reviewer'),'role',g.role,'region',g.region,'expires_at',g.expires_at) order by u.id,g.role),'[]') from public.user_roles g join auth.users u on u.id=g.user_id left join public.profiles p on p.id=u.id where g.active and g.revoked_at is null and(g.expires_at is null or g.expires_at>clock_timestamp()) and g.region=a.region and g.role in('scrutiny_officer','evc_coordinator','regional_officer') and u.id<>a.owner_id and u.email_confirmed_at is not null and(u.banned_until is null or u.banned_until<clock_timestamp()));end $$;
create function fp_private.operations_command(_kind text,_id uuid,_payload jsonb,_expected int,_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=fp_private.actor();a public.applications;review public.case_reviews;delivery public.delivery_outbox;receipt fp_private.control_receipts;body jsonb:=jsonb_build_object('operations',_kind,'id',_id,'payload',_payload,'expected',_expected);reason text:=trim(_payload->>'note');target uuid;result jsonb:='{}';source text;generation int;
begin
 if _kind='review_record' or _kind='review_cancel' then select * into review from public.case_reviews where id=_id;_id:=review.application_id;
 elsif _kind='outbox_retry' or _kind='outbox_cancel' then select * into delivery from public.delivery_outbox where id=_id;_id:=delivery.application_id;end if;
 select * into a from public.applications where id=_id for update;
 if a.id is null or not fp_private.can_view(a.id) then raise exception 'Case unavailable' using errcode='42501';end if;
 if _kind='review_record' then
  if review.reviewer_id<>uid or not exists(select 1 from public.user_roles g where g.user_id=uid and g.region=a.region and g.role in('scrutiny_officer','evc_coordinator','regional_officer') and g.active and g.revoked_at is null and(g.expires_at is null or g.expires_at>clock_timestamp())) then raise exception 'Assigned live reviewer grant required' using errcode='42501';end if;
 elsif not fp_private.can_manage_case(a) then raise exception 'Regional case manager required' using errcode='42501';end if;
 select * into receipt from fp_private.control_receipts where request_id=_request;if found then if receipt.actor_id<>uid or receipt.input<>body then raise exception 'Request ID already used';end if;return receipt.result;end if;
 if _expected is distinct from a.version then raise exception 'Case changed; reload before acting' using errcode='40001';end if;
 if coalesce(length(reason),0) not between 10 and 2000 then raise exception 'Recorded operational reason required';end if;
 if _kind='assign_case' then
  if a.status not in('submitted','resubmitted','under_scrutiny') then raise exception 'Assignment requires an open scrutiny case';end if;target:=(_payload->>'reviewer_id')::uuid;
  if not exists(select 1 from jsonb_array_elements(fp_private.candidates(a.id)) x where x->>'id'=target::text and x->>'role'='scrutiny_officer') then raise exception 'Active scrutiny officer in case region required';end if;
  update public.applications set assigned_officer=target,version=version+1,updated_at=now() where id=a.id;
 elsif _kind='review_assign' then
  if a.status not in('under_scrutiny','pending_decision','rejected') or coalesce(_payload->>'kind','') not in('second_opinion','appeal_review') or jsonb_typeof(_payload->'mandatory') is distinct from 'boolean' then raise exception 'Supported open review stage, kind and explicit requirement required';end if;
  target:=(_payload->>'reviewer_id')::uuid;if target=uid or not exists(select 1 from jsonb_array_elements(fp_private.candidates(a.id)) x where x->>'id'=target::text) then raise exception 'A different eligible reviewer in case region required';end if;
  insert into public.case_reviews(application_id,kind,reviewer_id,assigned_by,mandatory,basis_hash,assignment_reason) values(a.id,_payload->>'kind',target,uid,(_payload->>'mandatory')::boolean,fp_private.case_content(a.id),reason) returning * into review;result:=to_jsonb(review);
 elsif _kind='review_record' then
  if review.status<>'pending' or review.basis_hash<>fp_private.case_content(a.id) or coalesce(_payload->>'recommendation','') not in('recommend','conditions','not_recommend') or length(reason)<20 or jsonb_typeof(_payload->'evidence_ids') is distinct from 'array' or jsonb_array_length(_payload->'evidence_ids')=0 then raise exception 'Current assigned review, supported recommendation and case evidence required';end if;
  if exists(select 1 from jsonb_array_elements_text(_payload->'evidence_ids') x where not exists(select 1 from public.application_documents d where d.id=x::uuid and d.application_id=a.id and d.scan_status='clean')) then raise exception 'Clean evidence from this case required';end if;
  update public.case_reviews set status='completed',recommendation=_payload->>'recommendation',note=reason,recorded_at=now(),evidence_ids=array(select value::uuid from jsonb_array_elements_text(_payload->'evidence_ids')) where id=review.id;
 elsif _kind='review_cancel' then
  if review.status='cancelled' then raise exception 'Review already cancelled';end if;update public.case_reviews set status='cancelled',note=reason where id=review.id;
 elsif _kind='outbox_queue' then
  if not a.is_demo or coalesce(_payload->>'channel','') not in('in_app','smtp_local') then raise exception 'Synthetic case and supported local demonstration channel required';end if;
  if not exists(select 1 from public.user_roles g join auth.users u on u.id=g.user_id where g.user_id=a.owner_id and g.role='institution' and g.active and g.revoked_at is null and(g.expires_at is null or g.expires_at>clock_timestamp()) and u.email_confirmed_at is not null and(u.banned_until is null or u.banned_until<clock_timestamp())) then raise exception 'Live institution recipient required';end if;
  source:=fp_private.delivery_source(a.id,a.owner_id);if exists(select 1 from public.delivery_outbox o where o.application_id=a.id and o.channel=_payload->>'channel' and o.source_hash=source and o.status not in('superseded','cancelled','exhausted')) then raise exception 'This source already has a delivery intent';end if;
  select coalesce(max(o.generation),0)+1 into generation from public.delivery_outbox o where o.application_id=a.id;
  insert into public.delivery_outbox(application_id,recipient_id,channel,generation,source_hash,title,body) values(a.id,a.owner_id,_payload->>'channel',generation,source,'Demo case update · '||a.ref_no,'Synthetic case '||a.ref_no||' is '||a.status||'. '||reason) returning * into delivery;result:=to_jsonb(delivery);
 elsif _kind in('outbox_retry','outbox_cancel') then
  if delivery.status not in('retry_wait','exhausted','pending','ambiguous') then raise exception 'This delivery cannot be retried or cancelled';end if;
  if _kind='outbox_retry' and delivery.status='ambiguous' then raise exception 'Ambiguous SMTP acceptance requires human reconciliation; automatic resend is blocked';end if;
  update public.delivery_outbox set status=case when _kind='outbox_cancel' then 'cancelled' when source_hash<>fp_private.delivery_source(a.id,recipient_id) then 'superseded' else 'pending' end,scheduled_for=now(),last_error=reason where id=delivery.id;
 else raise exception 'Unsupported operational command';end if;
 if _kind in('review_assign','review_record','review_cancel') then update public.applications set version=version+1,updated_at=now() where id=a.id;end if;
 perform fp_private.event(a.id,'operations_'||_kind,a.status,a.status,reason,jsonb_build_object('request_id',_request,'review_id',review.id,'delivery_id',delivery.id,'assigned_to',target));
 insert into fp_private.control_receipts values(_request,uid,body,result);return result;
end $$;
alter function fp_private.transition(uuid,text,text,jsonb,int,uuid) rename to transition_before_operations;
create function fp_private.transition(_id uuid,_action text,_reason text,_payload jsonb,_expected_version int,_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=fp_private.actor();a public.applications;
begin select * into a from public.applications where id=_id for update;
 if a.id is null or not fp_private.can_view(a.id) or _expected_version is distinct from a.version then return fp_private.transition_before_operations(_id,_action,_reason,_payload,_expected_version,_request_id);end if;
 if _action='start_scrutiny' and a.assigned_officer is not null and a.assigned_officer<>uid then raise exception 'This case is allocated to a different scrutiny officer' using errcode='42501';end if;
 if _action in('approve','reject') and a.status='pending_decision' and exists(select 1 from public.case_reviews r where r.application_id=a.id and r.mandatory and r.status<>'cancelled' and(r.status<>'completed' or r.basis_hash<>fp_private.case_content(a.id))) then raise exception 'Complete or explicitly cancel the current mandatory additional review before deciding';end if;
 return fp_private.transition_before_operations(_id,_action,_reason,_payload,_expected_version,_request_id);
end $$;
create function fp_private.calendar_stage_target() returns trigger language plpgsql security definer set search_path='' as $$
declare stage_key text;days int;
begin if new.status<>old.status and new.template_snapshot?'calendar' and new.status not in('draft','deficiency_raised','approved','rejected') then stage_key:=case when new.status in('evc_pending','evc_scheduled') then 'evc' when new.status='pending_decision' then 'decision' else 'scrutiny' end;select (x->>'sla_days')::int into days from jsonb_array_elements(new.template_snapshot->'stages') x where x->>'key'=stage_key;new.sla_due_at:=fp_private.policy_due(now(),coalesce(days,7),new.template_snapshot->'calendar');end if;return new;end $$;
create trigger b_calendar_stage_target before update on public.applications for each row execute function fp_private.calendar_stage_target();
create function fp_private.outbox_claim(_limit int) returns jsonb language plpgsql security definer set search_path='' as $$
declare row public.delivery_outbox;a public.applications;result jsonb:='[]';token uuid;item record;
begin
 insert into public.worker_health values('local-delivery',now(),jsonb_build_object('state','claiming','transport','loopback only')) on conflict(id) do update set last_seen_at=excluded.last_seen_at,detail=excluded.detail;
 for item in select * from(select id,application_id from public.delivery_outbox where (status in('pending','retry_wait') and scheduled_for<=clock_timestamp()) or(status='processing' and lease_until<clock_timestamp()) order by created_at,id limit least(greatest(_limit,1),100)) batch order by application_id,id loop
  select * into a from public.applications where id=item.application_id for update;select * into row from public.delivery_outbox where id=item.id and((status in('pending','retry_wait') and scheduled_for<=clock_timestamp()) or(status='processing' and lease_until<clock_timestamp())) for update skip locked;if row.id is null then continue;end if;
  if row.status='processing' and row.channel='smtp_local' then update public.delivery_outbox set status='ambiguous',last_error='Worker lease expired; transport acceptance must be reconciled',lease_until=null where id=row.id;continue;end if;
  if row.source_hash<>fp_private.delivery_source(a.id,row.recipient_id) or not exists(select 1 from public.user_roles g join auth.users u on u.id=g.user_id where g.user_id=row.recipient_id and g.role='institution' and g.active and g.revoked_at is null and(g.expires_at is null or g.expires_at>clock_timestamp()) and u.email_confirmed_at is not null and(u.banned_until is null or u.banned_until<clock_timestamp())) then update public.delivery_outbox set status='superseded',last_error='Source or recipient authority changed before dispatch' where id=row.id;continue;end if;
  token:=gen_random_uuid();insert into fp_private.delivery_leases values(row.id,token) on conflict(id) do update set token=excluded.token;
  update public.delivery_outbox set status='processing',attempts=attempts+1,lease_until=now()+interval '2 minutes' where id=row.id returning * into row;result:=result||jsonb_build_array(to_jsonb(row)||jsonb_build_object('lease_token',token));
 end loop;return result;
end $$;
create function fp_private.outbox_finish(_id uuid,_token uuid,_outcome text,_detail text) returns text language plpgsql security definer set search_path='' as $$
declare row public.delivery_outbox;a public.applications;result text;
begin select a1.* into a from public.applications a1 join public.delivery_outbox o on o.application_id=a1.id where o.id=_id for update of a1;select * into row from public.delivery_outbox where id=_id for update;
 if row.status<>'processing' or row.lease_until<clock_timestamp() or not exists(select 1 from fp_private.delivery_leases l where l.id=_id and l.token=_token) then raise exception 'Current worker lease required';end if;
 if _outcome not in('in_app_delivered','smtp_accepted','ambiguous','retry_wait') or (_outcome='in_app_delivered' and row.channel<>'in_app') or(_outcome='smtp_accepted' and row.channel<>'smtp_local') then raise exception 'Unsupported delivery outcome';end if;
 result:=case when _outcome='retry_wait' and row.attempts>=5 then 'exhausted' else _outcome end;
 if row.source_hash<>fp_private.delivery_source(a.id,row.recipient_id) then result:=case when _outcome='smtp_accepted' then 'ambiguous' else 'superseded' end;end if;
 if result='in_app_delivered' then insert into public.notifications(user_id,title,body,application_id,outbox_id) values(row.recipient_id,row.title,row.body,row.application_id,row.id) on conflict(outbox_id) do nothing;end if;
 update public.delivery_outbox set status=result,lease_until=null,last_error=left(_detail,1000),accepted_at=case when result in('in_app_delivered','smtp_accepted') then now() else null end,scheduled_for=now()+make_interval(secs=>least(3600,30*power(2,least(row.attempts,7))::int)) where id=row.id;
 delete from fp_private.delivery_leases where id=row.id;insert into public.worker_health values('local-delivery',now(),jsonb_build_object('state',result,'last_intent',row.id)) on conflict(id) do update set last_seen_at=excluded.last_seen_at,detail=excluded.detail;return result;
end $$;
create function fp_private.readiness() returns jsonb language plpgsql security definer set search_path='' as $$
begin if not(fp_private.has_role('national_admin') or fp_private.has_role('regional_officer')) then raise exception 'Operational oversight role required' using errcode='42501';end if;
 return jsonb_build_object('checked_at',clock_timestamp(),'checks',jsonb_build_array(jsonb_build_object('name','Database and permission boundary','state','pass','detail','Authenticated role and current schema are callable.'),jsonb_build_object('name','Private document bucket configuration','state',case when exists(select 1 from storage.buckets where id='application-docs' and not public) then 'pass' else 'attention' end,'detail','Configuration check only; byte upload/download and quarantine integration require a live stack.'),jsonb_build_object('name','Local delivery worker heartbeat','state',case when exists(select 1 from public.worker_health where id='local-delivery' and last_seen_at>now()-interval '5 minutes') then 'pass' else 'attention' end,'detail','A recent heartbeat confirms activity, not end-to-end delivery.'),jsonb_build_object('name','Recovery and scanning release gates','state','attention','detail','A documented restore drill and integrated malware scanner must be verified separately.')));
end $$;
create function public.fp_operations_command(_kind text,_id uuid,_payload jsonb,_expected int,_request uuid) returns jsonb language sql security invoker set search_path='' as $$select fp_private.operations_command(_kind,_id,_payload,_expected,_request)$$;
create function public.fp_case_candidates(_id uuid) returns jsonb language sql security invoker set search_path='' as $$select fp_private.candidates(_id)$$;
create function public.fp_operational_readiness() returns jsonb language sql security invoker set search_path='' as $$select fp_private.readiness()$$;
create function public.fp_outbox_claim(_limit int) returns jsonb language sql security invoker set search_path='' as $$select fp_private.outbox_claim(_limit)$$;
create function public.fp_outbox_finish(_id uuid,_token uuid,_outcome text,_detail text) returns text language sql security invoker set search_path='' as $$select fp_private.outbox_finish(_id,_token,_outcome,_detail)$$;
revoke all on function fp_private.case_content(uuid),fp_private.delivery_source(uuid,uuid),fp_private.can_manage_case(public.applications),fp_private.candidates(uuid),fp_private.operations_command(text,uuid,jsonb,int,uuid),fp_private.transition_before_operations(uuid,text,text,jsonb,int,uuid),fp_private.transition(uuid,text,text,jsonb,int,uuid),fp_private.readiness(),fp_private.outbox_claim(int),fp_private.outbox_finish(uuid,uuid,text,text),public.fp_operations_command(text,uuid,jsonb,int,uuid),public.fp_case_candidates(uuid),public.fp_operational_readiness(),public.fp_outbox_claim(int),public.fp_outbox_finish(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function fp_private.can_manage_case(public.applications),fp_private.candidates(uuid),fp_private.operations_command(text,uuid,jsonb,int,uuid),fp_private.transition(uuid,text,text,jsonb,int,uuid),fp_private.readiness(),public.fp_operations_command(text,uuid,jsonb,int,uuid),public.fp_case_candidates(uuid),public.fp_operational_readiness() to authenticated;
grant execute on function fp_private.outbox_claim(int),fp_private.outbox_finish(uuid,uuid,text,text),public.fp_outbox_claim(int),public.fp_outbox_finish(uuid,uuid,text,text) to service_role;
alter function fp_private.analysis_facts(uuid) rename to analysis_facts_before_operations;
create function fp_private.analysis_facts(_id uuid) returns jsonb language sql stable security definer set search_path='' set timezone='UTC' as $$select fp_private.analysis_facts_before_operations(_id)||jsonb_build_object('case_reviews',(select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('basis_current',r.basis_hash=fp_private.case_content(_id)) order by r.id),'[]') from public.case_reviews r where r.application_id=_id))$$;
revoke all on function fp_private.analysis_facts_before_operations(uuid),fp_private.analysis_facts(uuid) from public,anon,authenticated;
notify pgrst,'reload schema';commit;
